window.SHIORI_DATA=window.SHIORI_DATA||{};SHIORI_DATA['n1_grammar']=[{"pattern":"〜が早いか","meaning":"as soon as; no sooner than","formation":"Verb (dictionary form / た-form) + が早いか","note":"Two actions happen almost simultaneously. Used for observed past events, not the speaker's own intentions.","examples":[{"ja":"彼は家に帰るが早いか、部屋に閉じこもってしまった。","en":"No sooner had he gotten home than he shut himself up in his room."},{"ja":"ベルが鳴るが早いか、生徒たちは教室を飛び出した。","en":"The moment the bell rang, the students rushed out of the classroom."}],"id":"n1g1"},{"pattern":"〜や/〜や否や","meaning":"as soon as; the moment that","formation":"Verb (dictionary form) + や(否や)","note":"Literary, written style. The second event is usually a sudden reaction; not used for the speaker's own will.","examples":[{"ja":"彼女はその知らせを聞くや否や、泣き出した。","en":"The moment she heard the news, she burst into tears."},{"ja":"電車のドアが開くや、乗客が一斉に降りてきた。","en":"As soon as the train doors opened, the passengers poured out all at once."}],"id":"n1g2"},{"pattern":"〜なり","meaning":"as soon as; right after","formation":"Verb (dictionary form) + なり","note":"Both actions usually have the same third-person subject; the second is often unexpected. Not used for one's own plans.","examples":[{"ja":"父は家に帰るなり、ソファに倒れ込んだ。","en":"As soon as my father got home, he collapsed onto the sofa."},{"ja":"彼は私の顔を見るなり、怒り出した。","en":"The moment he saw my face, he started getting angry."}],"id":"n1g3"},{"pattern":"〜そばから","meaning":"no sooner ... than (again); as soon as (repeatedly)","formation":"Verb (dictionary form / た-form) + そばから","note":"For repeated situations where an effort is immediately undone; often expresses frustration.","examples":[{"ja":"子供たちは片付けるそばから部屋を散らかす。","en":"No sooner do I tidy up than the kids mess up the room again."},{"ja":"年のせいか、聞いたそばから忘れてしまう。","en":"Maybe it's my age, but I forget things as soon as I hear them."}],"id":"n1g4"},{"pattern":"〜てからというもの","meaning":"ever since ~","formation":"Verb (て-form) + からというもの","note":"Emphasizes a major change that has continued since a turning point; more emotional than 〜て以来.","examples":[{"ja":"子供が生まれてからというもの、生活が一変した。","en":"Ever since our child was born, our life has completely changed."},{"ja":"彼はタバコをやめてからというもの、毎朝ジョギングをしている。","en":"Ever since he quit smoking, he has been jogging every morning."}],"id":"n1g5"},{"pattern":"〜を皮切りに","meaning":"starting with ~; beginning with ~","formation":"Noun + を皮切りに(して) / を皮切りとして","note":"Marks the first of a series of similar events that follow one after another.","examples":[{"ja":"そのバンドは東京を皮切りに、全国ツアーを行う。","en":"Starting with Tokyo, the band will go on a nationwide tour."},{"ja":"彼の発言を皮切りに、次々と反対意見が出た。","en":"Beginning with his remark, objections were raised one after another."}],"id":"n1g6"},{"pattern":"〜をもって","meaning":"by means of; with; as of (a time)","formation":"Noun + をもって","note":"Formal; common in announcements. Marks an end point in time or the means used. Humble form: をもちまして.","examples":[{"ja":"本日をもって閉店いたします。","en":"We will close our store as of today."},{"ja":"結果は書面をもってお知らせします。","en":"We will notify you of the results in writing."},{"ja":"これをもちまして本日の会を終了いたします。","en":"With this, we conclude today's meeting."}],"id":"n1g7"},{"pattern":"〜をもってすれば/〜をもってしても","meaning":"if one uses ~ (it's possible) / even with ~ (still impossible)","formation":"Noun + をもってすれば / をもってしても","note":"The noun is an impressive ability or means. すれば leads to success; しても to failure despite it.","examples":[{"ja":"彼の実力をもってすれば、優勝も夢ではない。","en":"With his ability, winning the championship is not just a dream."},{"ja":"最新の医学をもってしても、この病気は治せない。","en":"Even with the latest medicine, this disease cannot be cured."}],"id":"n1g8"},{"pattern":"〜を限りに","meaning":"as of ~ (and no longer); starting after ~","formation":"Noun (time) + を限りに","note":"Marks the last time something happens; common in announcements of retirement, closure or quitting.","examples":[{"ja":"今日を限りにタバコをやめる。","en":"As of today, I'm quitting smoking."},{"ja":"彼女は今季を限りに引退することを発表した。","en":"She announced that she would retire at the end of this season."}],"id":"n1g9"},{"pattern":"〜に至るまで","meaning":"even down to ~; all the way to ~","formation":"Noun + に至るまで","note":"Emphasizes a wide range reaching an unexpected or extreme point. Often paired with 〜から.","examples":[{"ja":"彼女は服から靴に至るまで、すべてブランド品だ。","en":"From her clothes down to her shoes, everything she wears is designer brand."},{"ja":"この事件は子供から老人に至るまで、{誰|だれ}もが知っている。","en":"Everyone, from children to the elderly, knows about this incident."}],"id":"n1g10"},{"pattern":"〜に至っては","meaning":"as for ~ (the most extreme case); when it comes to ~","formation":"Noun + に至っては","note":"Introduces the most extreme example in a series, usually negative.","examples":[{"ja":"今年は皆成績が悪く、田中さんに至っては全科目不合格だった。","en":"Everyone's grades were bad this year; as for Tanaka, he failed every subject."},{"ja":"家族は皆反対している。祖父に至っては口もきいてくれない。","en":"My whole family is against it. My grandfather won't even speak to me."}],"id":"n1g11"},{"pattern":"〜に至って/〜に至っても","meaning":"only when it came to ~ / even when it reached ~","formation":"Verb (dictionary form) / Noun + に至って(はじめて) / に至っても","note":"に至って: only at a serious stage did something finally happen. に至っても: even then, still nothing changed.","examples":[{"ja":"死者が出るに至って、ようやく国は対策に乗り出した。","en":"Only when people died did the government finally take measures."},{"ja":"倒産するに至っても、社長は自分の責任を認めなかった。","en":"Even when the company went bankrupt, the president did not admit his responsibility."}],"id":"n1g12"},{"pattern":"〜かたわら","meaning":"while also ~; besides (one's main work)","formation":"Verb (dictionary form) / Noun + の + かたわら","note":"Describes a long-term side activity alongside one's main occupation, not two momentary simultaneous actions.","examples":[{"ja":"彼は会社に勤めるかたわら、小説を書いている。","en":"While working at a company, he also writes novels."},{"ja":"母は子育てのかたわら、ボランティア活動にも参加している。","en":"While raising children, my mother also takes part in volunteer activities."}],"id":"n1g13"},{"pattern":"〜がてら","meaning":"while ~ (taking the opportunity to also do)","formation":"Verb (ます-stem) / Noun (action) + がてら","note":"Doing one thing also serves as a chance to do another; often with 散歩 and followed by movement verbs.","examples":[{"ja":"散歩がてら、パンを買いに行った。","en":"I went to buy some bread while taking a walk."},{"ja":"駅まで客を送りがてら、郵便局に寄った。","en":"While seeing my guest off to the station, I stopped by the post office."}],"id":"n1g14"},{"pattern":"〜かたがた","meaning":"while also ~; partly to ~ (formal)","formation":"Noun + かたがた","note":"Formal; used with nouns like お礼, ご報告, お見舞い, ご挨拶 in letters and business speech.","examples":[{"ja":"お礼かたがた、ご{挨拶|あいさつ}に伺いました。","en":"I came to greet you and to thank you at the same time."},{"ja":"近況のご報告かたがた、お手紙を差し上げます。","en":"I am writing to you, partly to let you know how I have been."}],"id":"n1g15"},{"pattern":"〜ところを","meaning":"although (you are) ~; at a time when ~","formation":"Verb (plain) / い-Adj / な-Adj + な / Noun + の + ところを","note":"Polite set phrases thanking or apologizing for an imposition, e.g. お忙しいところを, お休みのところを.","examples":[{"ja":"お忙しいところをお越しいただき、ありがとうございます。","en":"Thank you for coming when you are so busy."},{"ja":"お休みのところを申し訳ありません。","en":"I'm sorry to disturb you on your day off."}],"id":"n1g16"},{"pattern":"〜を経て","meaning":"through; via; after going through ~","formation":"Noun + を経て","note":"Passing through a place, stage, process or period before reaching a result.","examples":[{"ja":"彼は厳しい訓練を経て、一人前の職人になった。","en":"After going through rigorous training, he became a full-fledged craftsman."},{"ja":"この便はソウルを経てシンガポールへ向かいます。","en":"This flight goes to Singapore via Seoul."}],"id":"n1g17"},{"pattern":"〜にあって","meaning":"in (a situation/position); being in ~","formation":"Noun + にあって(は/も)","note":"Formal; stresses special circumstances. にあっても introduces a contrast.","examples":[{"ja":"非常時にあって、冷静な判断が求められる。","en":"In an emergency, calm judgment is required."},{"ja":"彼は社長という立場にあって、常に社員のことを考えている。","en":"In his position as president, he always thinks about his employees."}],"id":"n1g18"},{"pattern":"〜ともなると/〜ともなれば","meaning":"when it comes to ~; once (one reaches) ~","formation":"Noun / Verb (dictionary form) + ともなると / ともなれば","note":"On reaching a higher stage, status or special time, a naturally expected change follows.","examples":[{"ja":"大学生ともなると、自分のことは自分でしなければならない。","en":"Once you become a university student, you have to take care of yourself."},{"ja":"年末ともなれば、どこの店も混み合う。","en":"When the end of the year comes, every store gets crowded."}],"id":"n1g19"},{"pattern":"〜とあって","meaning":"because (of a special situation); since ~","formation":"Plain form / Noun + とあって","note":"A special circumstance and its natural, observed result. Describes objective facts; not used with requests.","examples":[{"ja":"連休とあって、観光地はどこも人でいっぱいだ。","en":"Since it's a long holiday weekend, tourist spots everywhere are packed."},{"ja":"有名な歌手が来るとあって、会場には大勢のファンが集まった。","en":"Because a famous singer was coming, a large crowd of fans gathered at the venue."}],"id":"n1g20"},{"pattern":"〜とあれば","meaning":"if it's (for) ~; if that's the case","formation":"Plain form / Noun + とあれば","note":"If the condition is special or important, one is willing to do something one normally wouldn't.","examples":[{"ja":"子供のためとあれば、どんな苦労もいとわない。","en":"If it's for my children, I don't mind any hardship."},{"ja":"社長の命令とあれば、従うしかない。","en":"If it's the president's order, we have no choice but to follow it."}],"id":"n1g21"},{"pattern":"〜とあっては","meaning":"if/since it is the case that ~ (then naturally)","formation":"Plain form / Noun + とあっては","note":"Given a special situation, a certain (often unavoidable or negative) result follows.","examples":[{"ja":"恩師の頼みとあっては、断るわけにはいかない。","en":"Since it's a request from my former teacher, I can't refuse."},{"ja":"こんなに雨が強いとあっては、試合は中止せざるを得ない。","en":"With the rain this heavy, we have no choice but to cancel the match."}],"id":"n1g22"},{"pattern":"〜に即して","meaning":"in accordance with ~; based on (facts, reality)","formation":"Noun + に即して / に即した + Noun","note":"Used with nouns like 事実, 現実, 実態, 法律: acting in line with actual circumstances or rules.","examples":[{"ja":"事実に即して報告してください。","en":"Please report in accordance with the facts."},{"ja":"現実に即した計画を立てるべきだ。","en":"We should make a plan that is grounded in reality."}],"id":"n1g23"},{"pattern":"〜に照らして","meaning":"in light of ~; judged against ~","formation":"Noun + に照らして / に照らすと","note":"Compares something against a standard such as law, rules or past cases in order to judge it.","examples":[{"ja":"法律に照らして判断すると、彼の行為は違法だ。","en":"Judged in light of the law, his act is illegal."},{"ja":"過去の例に照らして、今回の処分は重すぎる。","en":"In light of past cases, this punishment is too severe."}],"id":"n1g24"},{"pattern":"〜にのっとって","meaning":"in accordance with ~; following (rules, tradition)","formation":"Noun + にのっとって / にのっとった + Noun","note":"Formal; following established rules, customs or ceremonies. Kanji form: 則って.","examples":[{"ja":"試合はルールにのっとって行われる。","en":"The match is conducted in accordance with the rules."},{"ja":"結婚式は古来の伝統にのっとって執り行われた。","en":"The wedding was held in accordance with ancient tradition."}],"id":"n1g25"},{"pattern":"〜を踏まえて","meaning":"based on ~; taking ~ into account","formation":"Noun + を踏まえて / を踏まえた + Noun","note":"Formal; uses results, facts or opinions as the basis for the next step.","examples":[{"ja":"調査の結果を踏まえて、新しい方針を決めた。","en":"Based on the results of the survey, we decided on a new policy."},{"ja":"前回の反省を踏まえて、準備を進めている。","en":"We are moving ahead with preparations, taking into account the lessons from last time."}],"id":"n1g26"},{"pattern":"〜にかかわる","meaning":"affecting ~; that concerns (something serious)","formation":"Noun + にかかわる","note":"Used with serious matters such as 命, 名誉, 信用, 将来: something with a grave effect on them. Kanji: 関わる.","examples":[{"ja":"これは命にかかわる問題だ。","en":"This is a matter of life and death."},{"ja":"そんなことをすれば、会社の信用にかかわる。","en":"Doing such a thing would damage the company's credibility."}],"id":"n1g27"},{"pattern":"〜いかんで/〜いかんによって(は)","meaning":"depending on ~","formation":"Noun + (の) + いかんで / いかんによって(は) / いかんだ","note":"Formal equivalent of 〜次第で. Kanji form: 如何.","examples":[{"ja":"結果いかんでは、計画を中止することもある。","en":"Depending on the results, the plan may be canceled."},{"ja":"試験の成績いかんによって、合否が決まる。","en":"Whether you pass or fail depends on your test score."}],"id":"n1g28"},{"pattern":"〜いかんにかかわらず/〜いかんを問わず","meaning":"regardless of ~","formation":"Noun + (の) + いかんにかかわらず / いかんによらず / いかんを問わず","note":"Formal; common in official notices and terms and conditions.","examples":[{"ja":"理由のいかんにかかわらず、一度支払われた料金は返金できません。","en":"Regardless of the reason, fees once paid cannot be refunded."},{"ja":"年齢のいかんを問わず、どなたでも参加できます。","en":"Anyone can participate, regardless of age."}],"id":"n1g29"},{"pattern":"〜をおいて〜ない","meaning":"no one/nothing other than ~","formation":"Noun + をおいて(ほかに)〜ない","note":"Strongly praises something as the only suitable choice.","examples":[{"ja":"この仕事を任せられるのは、彼をおいてほかにいない。","en":"There is no one other than him whom we can entrust with this job."},{"ja":"日本の伝統文化を学ぶなら、京都をおいてほかにない。","en":"If you want to study traditional Japanese culture, there's no place but Kyoto."}],"id":"n1g30"},{"pattern":"〜はおろか","meaning":"let alone ~; not to mention ~","formation":"Noun + はおろか","note":"The first item is obvious; the second, more extreme item is stressed with も/さえ/まで. Usually negative.","examples":[{"ja":"彼は漢字はおろか、ひらがなも書けない。","en":"He can't even write hiragana, let alone kanji."},{"ja":"けがをして、走ることはおろか、歩くことさえできない。","en":"I'm injured and can't even walk, let alone run."}],"id":"n1g31"},{"pattern":"〜もさることながら","meaning":"~ is true, and moreover ~; not only ~ but also","formation":"Noun + もさることながら","note":"Acknowledges the first point but stresses the second as even more notable. Positive or neutral contexts.","examples":[{"ja":"この店は料理の味もさることながら、雰囲気も素晴らしい。","en":"This restaurant's food is good, of course, but the atmosphere is wonderful too."},{"ja":"彼女は容姿もさることながら、人柄が魅力的だ。","en":"Her looks aside, it's her personality that is really charming."}],"id":"n1g32"},{"pattern":"〜にとどまらず","meaning":"not limited to ~; going beyond ~","formation":"Noun / Verb (dictionary form) + にとどまらず","note":"Something extends beyond a certain range or scope.","examples":[{"ja":"その歌手の人気は国内にとどまらず、海外にも広がっている。","en":"The singer's popularity isn't limited to Japan; it has spread overseas too."},{"ja":"環境問題は一国にとどまらず、世界全体の問題だ。","en":"Environmental problems are not confined to one country but concern the whole world."}],"id":"n1g33"},{"pattern":"〜ならいざしらず/〜はいざしらず","meaning":"~ may be one thing, but; I don't know about ~, but","formation":"Noun + なら(ば)いざしらず / はいざしらず","note":"The first case might be excusable or different; the actual case is not. Kanji form: いざ知らず.","examples":[{"ja":"子供ならいざしらず、大人がそんなことをするなんて信じられない。","en":"It might be one thing for a child, but I can't believe an adult would do such a thing."},{"ja":"昔はいざしらず、今は{誰|だれ}でもインターネットで情報が得られる。","en":"I don't know about the old days, but now anyone can get information online."}],"id":"n1g34"},{"pattern":"〜ならまだしも","meaning":"~ would be acceptable, but; if it were ~ it'd be one thing, but","formation":"Noun / Plain form + ならまだしも","note":"The first situation would be barely tolerable; the actual one is not. Expresses dissatisfaction.","examples":[{"ja":"一度ならまだしも、何度も同じミスをするのは困る。","en":"Once would be acceptable, but making the same mistake again and again is a problem."},{"ja":"電話で謝るならまだしも、メール一通で済ませるなんて失礼だ。","en":"Apologizing by phone would be one thing, but settling it with a single email is rude."}],"id":"n1g35"},{"pattern":"〜はさておき","meaning":"setting ~ aside; leaving ~ aside","formation":"Noun + はさておき","note":"Temporarily puts one topic aside to focus on something more important. Also used as それはさておき.","examples":[{"ja":"冗談はさておき、そろそろ本題に入りましょう。","en":"Joking aside, let's get down to business."},{"ja":"費用の問題はさておき、まずは計画を立てよう。","en":"Setting aside the issue of cost, let's make a plan first."}],"id":"n1g36"},{"pattern":"〜すら","meaning":"even ~","formation":"Noun (+ particle) + すら / ですら","note":"Written equivalent of さえ; highlights an extreme example, usually with a negative result.","examples":[{"ja":"忙しくて、食事をする時間すらない。","en":"I'm so busy I don't even have time to eat."},{"ja":"この問題は専門家ですら解けなかった。","en":"Even experts couldn't solve this problem."}],"id":"n1g37"},{"pattern":"〜だに","meaning":"even just ~; not even ~","formation":"Verb (dictionary form) + だに / Noun + だに(しない)","note":"Literary; mostly set phrases: 想像するだに, 考えるだに, 夢にだに思わない, 微動だにしない.","examples":[{"ja":"大地震が起きたらと想像するだに恐ろしい。","en":"Just imagining a major earthquake is frightening."},{"ja":"兵士たちは微動だにせず立っていた。","en":"The soldiers stood without moving a muscle."}],"id":"n1g38"},{"pattern":"〜たりとも","meaning":"not even (a single) ~","formation":"一 + counter + たりとも + negative","note":"Used with the smallest unit (一円, 一日, 一瞬, 一人) to stress that not even that much is allowed.","examples":[{"ja":"試験まで一日たりとも無駄にはできない。","en":"I can't waste even a single day before the exam."},{"ja":"国民の税金は一円たりとも無駄にしてはならない。","en":"Not even one yen of taxpayers' money must be wasted."}],"id":"n1g39"},{"pattern":"〜からある/〜からする/〜からの","meaning":"as much as ~; no less than ~","formation":"Number + からある (size, weight) / からする (price) / からの + Noun (people, amounts)","note":"Stresses that a quantity is surprisingly large.","examples":[{"ja":"彼は50キロからある荷物を一人で運んだ。","en":"He carried luggage weighing as much as 50 kilograms by himself."},{"ja":"彼女は百万円からする時計を持っている。","en":"She owns a watch that costs a million yen or more."},{"ja":"そのコンサートには一万人からの人が集まった。","en":"As many as ten thousand people gathered for the concert."}],"id":"n1g40"},{"pattern":"〜にして","meaning":"only (someone at the level of) ~; at (the stage of) ~; both ~ and","formation":"Noun + にして","note":"Highlights a high level (この人にして初めて), an age or stage (40歳にして), or 'A and also B' (詩人にして画家).","examples":[{"ja":"彼ほどのベテランにして初めてできる技だ。","en":"It's a skill that only a veteran of his caliber could pull off."},{"ja":"彼は40歳にして初めて結婚した。","en":"He got married for the first time at the age of 40."},{"ja":"彼は詩人にして画家でもある。","en":"He is both a poet and a painter."}],"id":"n1g41"},{"pattern":"〜ならでは","meaning":"unique to ~; that only ~ can offer","formation":"Noun + ならではの + Noun / Noun + ならでは(だ)","note":"Praises qualities characteristic of a specific person, place or thing.","examples":[{"ja":"これは京都ならではの風景だ。","en":"This is scenery you can only find in Kyoto."},{"ja":"手作りならではの温かみがある。","en":"It has a warmth that only handmade things have."}],"id":"n1g42"},{"pattern":"〜きっての","meaning":"the most ~ in (a group/place)","formation":"Noun (group/place) + きっての + Noun","note":"Praises someone or something as the very best within an organization, region, etc.","examples":[{"ja":"彼は社内きっての切れ者だ。","en":"He is the sharpest person in the company."},{"ja":"ここは県内きっての名門校だ。","en":"This is the most prestigious school in the prefecture."}],"id":"n1g43"},{"pattern":"〜あっての","meaning":"~ is possible only because of ~","formation":"Noun A + あっての + Noun B","note":"B exists only thanks to A; often expresses gratitude, e.g. お客様あっての商売.","examples":[{"ja":"お客様あっての商売ですから、サービスを何より大切にしています。","en":"Our business exists only because of our customers, so we value service above all."},{"ja":"健康あっての人生だ。","en":"Without health, life is nothing."}],"id":"n1g44"},{"pattern":"〜ともあろう","meaning":"someone (of such standing) as ~","formation":"Noun (person/organization) + ともあろう + Noun","note":"Criticizes behavior unworthy of someone in a respected position; followed by a negative judgment.","examples":[{"ja":"教師ともあろう者が、生徒にうそをつくなんて。","en":"To think that a teacher, of all people, would lie to students!"},{"ja":"大企業ともあろう会社が、こんな初歩的なミスをするとは。","en":"That a major corporation should make such a basic mistake!"}],"id":"n1g45"},{"pattern":"〜たる","meaning":"as a ~; being (in the role of) ~","formation":"Noun + たる(者) / たる + Noun","note":"Literary; stresses the standards expected of someone in a role, often with べきだ or なければならない.","examples":[{"ja":"医師たる者、患者の命を第一に考えるべきだ。","en":"Anyone who is a doctor should put patients' lives first."},{"ja":"国の代表たる選手が、そんな態度をとるべきではない。","en":"An athlete who represents the country should not behave like that."}],"id":"n1g46"},{"pattern":"〜極まる/〜極まりない","meaning":"extremely ~; utterly ~","formation":"な-Adj (stem) + 極まる / 極まりない","note":"Both mean the same. Used with words like 失礼, 危険, 不愉快, 残念. Formal.","examples":[{"ja":"彼の態度は失礼極まりない。","en":"His attitude is extremely rude."},{"ja":"雨の夜に無灯火で自転車に乗るのは危険極まる。","en":"Riding a bicycle without a light on a rainy night is extremely dangerous."}],"id":"n1g47"},{"pattern":"〜の至り","meaning":"the height of ~; utmost ~","formation":"Noun + の至り","note":"Formal set phrases: 光栄の至り, 恐縮の至り, 感激の至り; also 若気の至り (youthful indiscretion).","examples":[{"ja":"このような賞をいただき、光栄の至りです。","en":"It is the greatest honor to receive such an award."},{"ja":"あれは若気の至りでした。","en":"That was a youthful indiscretion."}],"id":"n1g48"},{"pattern":"〜の極み","meaning":"the height of ~; the epitome of ~","formation":"Noun + の極み","note":"The ultimate degree of a feeling or state: 贅沢の極み, 疲労の極み, 痛恨の極み.","examples":[{"ja":"一流ホテルのスイートに泊まるなんて、{贅沢|ぜいたく}の極みだ。","en":"Staying in a suite at a top-class hotel is the height of luxury."},{"ja":"決勝で負けたことは痛恨の極みです。","en":"Losing in the final is a matter of the deepest regret."}],"id":"n1g49"},{"pattern":"〜ことこのうえない","meaning":"extremely ~; nothing could be more ~","formation":"い-Adj (dictionary form) / な-Adj + な + ことこのうえない","note":"Formal; expresses the highest degree. Kanji form: この上ない.","examples":[{"ja":"一人で夜道を歩くのは危険なことこのうえない。","en":"Walking alone at night is as dangerous as it gets."},{"ja":"彼の話は長くて退屈なことこのうえなかった。","en":"His talk was long and could not have been more boring."}],"id":"n1g50"},{"pattern":"〜といったらない","meaning":"extremely ~; indescribably ~","formation":"Noun / い-Adj (dictionary form) + といったらない","note":"Emotional emphasis of a feeling, positive or negative. Casual form: 〜ったらない.","examples":[{"ja":"富士山の頂上から見た景色の美しさといったらなかった。","en":"The view from the summit of Mt. Fuji was indescribably beautiful."},{"ja":"大勢の前で転んで、恥ずかしいといったらない。","en":"I fell in front of a crowd, and it was beyond embarrassing."}],"id":"n1g51"},{"pattern":"〜といったらありはしない","meaning":"unbearably ~; incredibly (annoying, etc.)","formation":"Noun / い-Adj (dictionary form) + といったらありはしない / ったらありゃしない","note":"Only for negative feelings. Colloquial form: 〜ったらありゃしない.","examples":[{"ja":"隣の工事の音がうるさいといったらありはしない。","en":"The noise from the construction next door is unbearably loud."},{"ja":"毎日満員電車で通勤するのは、疲れるったらありゃしない。","en":"Commuting on packed trains every day is exhausting beyond words."}],"id":"n1g52"},{"pattern":"〜にもほどがある","meaning":"there's a limit to ~; ~ goes too far","formation":"Noun / Verb (dictionary form) / い-Adj (dictionary form) + にもほどがある","note":"Criticizes something as excessive. Kanji form: 程.","examples":[{"ja":"冗談にもほどがある。","en":"There's a limit to joking around."},{"ja":"約束を三回も忘れるなんて、失礼にもほどがある。","en":"Forgetting our appointment three times is way too rude."}],"id":"n1g53"},{"pattern":"〜てやまない","meaning":"never cease to ~; sincerely ~","formation":"Verb (て-form) + やまない","note":"A strong, lasting feeling with verbs like 願う, 祈る, 愛する, 期待する. Common in speeches.","examples":[{"ja":"皆様のご健康とご活躍を願ってやみません。","en":"I sincerely wish you all good health and success."},{"ja":"彼は生涯、故郷を愛してやまなかった。","en":"He never stopped loving his hometown throughout his life."}],"id":"n1g54"},{"pattern":"〜を禁じ得ない","meaning":"cannot help feeling ~","formation":"Noun (emotion) + を禁じ得ない","note":"Formal; used with emotions like 同情, 怒り, 涙, 驚き that arise involuntarily.","examples":[{"ja":"被災者の話を聞いて、涙を禁じ得なかった。","en":"Hearing the disaster victims' stories, I couldn't hold back my tears."},{"ja":"政府の無責任な対応には怒りを禁じ得ない。","en":"I cannot help feeling anger at the government's irresponsible response."}],"id":"n1g55"},{"pattern":"〜にかたくない","meaning":"it is not hard to ~; easy to (imagine)","formation":"Verb (dictionary form) / Noun + にかたくない","note":"Almost only with 想像 or 察する: 想像にかたくない. Kanji form: 難くない.","examples":[{"ja":"子供を亡くした親の悲しみは想像にかたくない。","en":"It is not hard to imagine the grief of parents who have lost a child."},{"ja":"彼がどれほど苦労したかは、察するにかたくない。","en":"It's easy to guess how much he went through."}],"id":"n1g56"},{"pattern":"〜に足る/〜に足りない","meaning":"worthy of ~; enough to ~ / not worth ~","formation":"Verb (dictionary form) / Noun + に足る / に足りない","note":"に足る: deserving (信頼に足る人物). に足りない: trivial (取るに足りない, 恐れるに足りない).","examples":[{"ja":"彼は信頼するに足る人物だ。","en":"He is a person worthy of trust."},{"ja":"そんな取るに足りないことで悩む必要はない。","en":"There's no need to worry about something so trivial."}],"id":"n1g57"},{"pattern":"〜にたえる/〜にたえない","meaning":"worth ~ / cannot bear ~; deeply (grateful etc.)","formation":"Verb (dictionary form) / Noun + にたえる / にたえない","note":"見るにたえない: too awful to watch. 感謝にたえない: extremely grateful. Kanji form: 堪える.","examples":[{"ja":"この作品は大人の鑑賞にもたえる内容だ。","en":"This work has content that is worth appreciating even for adults."},{"ja":"事故現場は見るにたえない光景だった。","en":"The scene of the accident was too horrible to look at."},{"ja":"皆様のご支援には感謝にたえません。","en":"I am deeply grateful for everyone's support."}],"id":"n1g58"},{"pattern":"〜に値する","meaning":"worth ~; deserve ~","formation":"Verb (dictionary form) / Noun + に値する","note":"Something deserves an action or evaluation; often with 称賛, 注目, 一読, 検討.","examples":[{"ja":"彼の勇気ある行動は称賛に値する。","en":"His courageous action deserves praise."},{"ja":"この本は一読に値する。","en":"This book is worth reading."}],"id":"n1g59"},{"pattern":"〜とはいえ","meaning":"although ~; even though ~","formation":"Plain form / Noun + とはいえ","note":"Admits a fact but adds that reality differs from what it implies. Formal; also used sentence-initially.","examples":[{"ja":"春とはいえ、まだ寒い日が続いている。","en":"Although it's spring, cold days are still continuing."},{"ja":"仕事とはいえ、家族と離れて暮らすのはつらい。","en":"Even if it's for work, living apart from my family is hard."}],"id":"n1g60"},{"pattern":"〜といえども","meaning":"even though ~; even ~","formation":"Plain form / Noun + といえども","note":"Formal, literary; stresses that even a notable case is no exception. Often with たとえ or いかに.","examples":[{"ja":"子供といえども、法律を守らなければならない。","en":"Even children must obey the law."},{"ja":"いかに優れた専門家といえども、間違うことはある。","en":"No matter how excellent an expert is, they can still make mistakes."}],"id":"n1g61"},{"pattern":"〜ものを","meaning":"if only ~ (but); although ~ (regret, reproach)","formation":"Plain form + ものを","note":"Expresses regret or reproach that something wasn't done; like のに but more emotional. Often with 〜ば.","examples":[{"ja":"一言相談してくれれば手伝ったものを。","en":"If only you had said something, I would have helped."},{"ja":"すぐに病院へ行けば治ったものを、彼は放っておいた。","en":"It would have healed if he'd gone to the hospital right away, but he left it alone."}],"id":"n1g62"},{"pattern":"〜とて","meaning":"even ~; even if ~","formation":"Noun + とて / Verb (た-form) + とて","note":"Literary. Noun + とて: 'even X is no exception'. Verb + たとて: 'even if' (= たとしても).","examples":[{"ja":"私とて、彼の気持ちがわからないわけではない。","en":"It's not that I don't understand how he feels either."},{"ja":"親とて人間だ。間違うこともある。","en":"Parents are human too. They make mistakes sometimes."},{"ja":"いくら頼んだとて、無理なものは無理だ。","en":"No matter how much you ask, what's impossible is impossible."}],"id":"n1g63"},{"pattern":"〜であれ/〜であれ〜であれ","meaning":"whatever ~; whether ~ or ~","formation":"Noun + であれ / Noun A + であれ + Noun B + であれ","note":"Formal; the conclusion holds whatever the case. Often with 何/誰/どこ + であれ.","examples":[{"ja":"理由が何であれ、暴力は許されない。","en":"Whatever the reason, violence is not acceptable."},{"ja":"大人であれ子供であれ、ルールは守るべきだ。","en":"Whether adult or child, everyone should follow the rules."}],"id":"n1g64"},{"pattern":"〜(よ)うが/〜(よ)うと","meaning":"no matter ~; even if ~","formation":"Verb (volitional) / い-Adj (〜かろう) / Noun・な-Adj + だろう + が/と","note":"Often with question words (何を言われようが, どこへ行こうと). The main clause is unaffected by the condition.","examples":[{"ja":"{誰|だれ}が何と言おうが、私の気持ちは変わらない。","en":"No matter what anyone says, my feelings won't change."},{"ja":"どんなに苦しかろうと、最後まで頑張るつもりだ。","en":"However hard it may be, I intend to keep going until the end."}],"id":"n1g65"},{"pattern":"〜(よ)うが〜まいが/〜(よ)うと〜まいと","meaning":"whether or not ~","formation":"Verb (volitional) + が/と + same Verb + まいが/まいと","note":"The same verb in affirmative and negative; the result is the same either way.","examples":[{"ja":"雨が降ろうが降るまいが、試合は行われる。","en":"Whether it rains or not, the match will be held."},{"ja":"君が来ようと来るまいと、私は行く。","en":"Whether you come or not, I'm going."}],"id":"n1g66"},{"pattern":"〜(よ)うとも","meaning":"even if ~; no matter how ~","formation":"Verb (volitional) / い-Adj (〜かろう) + とも","note":"Literary version of 〜ても; often with たとえ or どんなに.","examples":[{"ja":"たとえ反対されようとも、私はこの道を進む。","en":"Even if people oppose me, I will continue down this path."},{"ja":"どんなに遠かろうとも、会いに行きます。","en":"No matter how far it is, I'll go to see you."}],"id":"n1g67"},{"pattern":"〜たところで","meaning":"even if ~ (it would be pointless)","formation":"Verb (た-form) + ところで","note":"The action would be useless or achieve little; followed by a negative or pessimistic judgment.","examples":[{"ja":"今から急いだところで、終電には間に合わない。","en":"Even if we hurry now, we won't make the last train."},{"ja":"彼に謝ったところで、許してはくれないだろう。","en":"Even if I apologize to him, he probably won't forgive me."}],"id":"n1g68"},{"pattern":"〜としたところで/〜としたって","meaning":"even supposing ~; even for ~","formation":"Plain form / Noun + としたところで / としたって","note":"Even assuming something, the outcome won't change; also 'even from X's standpoint'. としたって is casual.","examples":[{"ja":"今から申し込むとしたところで、もう席は残っていないだろう。","en":"Even if we applied now, there probably wouldn't be any seats left."},{"ja":"私としたって、好きでこんなことを言っているわけではない。","en":"Even for me, it's not as if I enjoy saying this."}],"id":"n1g69"},{"pattern":"〜にしたって","meaning":"even ~; even if ~ (casual)","formation":"Noun / Plain form + にしたって","note":"Conversational form of にしても; says the same applies even to the case mentioned.","examples":[{"ja":"冗談にしたって、言っていいことと悪いことがある。","en":"Even as a joke, there are things you should and shouldn't say."},{"ja":"先生にしたって、すべての答えを知っているわけではない。","en":"Even teachers don't know all the answers."}],"id":"n1g70"},{"pattern":"〜ようにも〜ない","meaning":"even if one wants to ~, one can't","formation":"Verb (volitional) + にも + same Verb (potential, negative)","note":"Something is impossible despite the intention, because of circumstances.","examples":[{"ja":"お金がなくて、旅行に行こうにも行けない。","en":"I have no money, so I can't go on a trip even if I want to."},{"ja":"電話番号を知らないので、連絡しようにもできない。","en":"I don't know his phone number, so I can't contact him even if I want to."}],"id":"n1g71"},{"pattern":"〜(よ)うものなら","meaning":"if (someone) were to ~ (something terrible would happen)","formation":"Verb (volitional) + ものなら","note":"Warns that even a small action would lead to serious consequences; the result is often exaggerated.","examples":[{"ja":"社長の前でそんなことを言おうものなら、すぐに首になるよ。","en":"If you said something like that in front of the president, you'd be fired immediately."},{"ja":"少しでも遅刻しようものなら、先生にひどく{叱|しか}られる。","en":"If you're even a little late, the teacher scolds you severely."}],"id":"n1g72"},{"pattern":"〜が最後/〜たら最後","meaning":"once ~ (then it's all over)","formation":"Verb (た-form) + が最後 / Verb (たら-form) + 最後","note":"Once something happens, an irreversible, usually bad situation inevitably follows.","examples":[{"ja":"彼は寝たが最後、何があっても起きない。","en":"Once he falls asleep, nothing will wake him up."},{"ja":"このゲームは始めたら最後、なかなかやめられない。","en":"Once you start this game, it's hard to stop."}],"id":"n1g73"},{"pattern":"〜ばそれまでだ","meaning":"if ~, that's the end of it","formation":"Verb (ば-form) + それまでだ / Verb (たら-form) + それまでだ","note":"If a certain thing happens, everything else becomes pointless.","examples":[{"ja":"いくらお金を貯めても、死んでしまえばそれまでだ。","en":"No matter how much money you save, once you die, that's the end of it."},{"ja":"どんなにいい計画でも、実行しなければそれまでだ。","en":"However good a plan is, if you don't carry it out, it comes to nothing."}],"id":"n1g74"},{"pattern":"〜なくして(は)","meaning":"without ~ (something is impossible)","formation":"Noun + なくして(は) + negative","note":"Something is indispensable; followed by a negative or impossible result. Formal.","examples":[{"ja":"努力なくして成功はありえない。","en":"There can be no success without effort."},{"ja":"皆様のご協力なくしては、このプロジェクトは完成しませんでした。","en":"Without everyone's cooperation, this project would not have been completed."}],"id":"n1g75"},{"pattern":"〜なしに(は)/〜ことなしに","meaning":"without ~ (doing)","formation":"Noun + なしに(は) / Verb (dictionary form) + ことなしに(は)","note":"Formal. With は + negative, it means the thing is a prerequisite.","examples":[{"ja":"彼は断りなしに会議を欠席した。","en":"He missed the meeting without giving notice."},{"ja":"人は他人と関わることなしには生きていけない。","en":"People cannot live without interacting with others."}],"id":"n1g76"},{"pattern":"〜ないまでも","meaning":"even if not ~, at least ~","formation":"Verb (ない-form) + までも","note":"Even if a higher level isn't reached, at least a lower level is expected. Often with せめて or 少なくとも.","examples":[{"ja":"毎日とは言わないまでも、週に一度は運動したほうがいい。","en":"Maybe not every day, but you should exercise at least once a week."},{"ja":"優勝はできないまでも、決勝までは進みたい。","en":"Even if we can't win, I'd like to at least make it to the final."}],"id":"n1g77"},{"pattern":"〜ずとも","meaning":"even without ~; even if one doesn't ~","formation":"Verb (ない-stem) + ずとも (する → せずとも)","note":"Literary form of 〜なくても; often followed by いい or わかる.","examples":[{"ja":"そんなことは言わずともわかっている。","en":"I know that without you having to say it."},{"ja":"心配せずとも、彼ならきっと大丈夫だ。","en":"There's no need to worry; he'll surely be fine."}],"id":"n1g78"},{"pattern":"〜ないものでもない","meaning":"it's not impossible that ~; might ~","formation":"Verb (ない-form) + ものでもない","note":"A hesitant, reluctant possibility; something could be done under certain conditions.","examples":[{"ja":"条件によっては、引き受けないものでもない。","en":"Depending on the conditions, I might take it on."},{"ja":"今から頑張れば、合格できないものでもない。","en":"If you work hard from now on, passing is not out of the question."}],"id":"n1g79"},{"pattern":"〜ではあるまいし","meaning":"it's not as if ~; since ~ isn't the case","formation":"Noun + ではあるまいし / Verb (plain) + わけではあるまいし","note":"Followed by criticism or advice. Colloquial form: じゃあるまいし.","examples":[{"ja":"子供ではあるまいし、自分のことは自分でしなさい。","en":"You're not a child, so take care of yourself."},{"ja":"一生会えないわけではあるまいし、そんなに泣かないで。","en":"It's not as if we'll never see each other again, so don't cry like that."}],"id":"n1g80"},{"pattern":"〜と思いきや","meaning":"I thought ~, but actually ~","formation":"Plain form + と思いきや","note":"The result was contrary to expectation; written or narrative style.","examples":[{"ja":"試験は簡単だと思いきや、意外に難しかった。","en":"I thought the exam would be easy, but it was unexpectedly difficult."},{"ja":"やっと終わったと思いきや、また新しい仕事を頼まれた。","en":"Just when I thought I was finally done, I was asked to do another job."}],"id":"n1g81"},{"pattern":"〜ばこそ","meaning":"precisely because ~","formation":"Verb / Adj (ば-form) + こそ / Noun + であればこそ","note":"Emphasizes a positive reason, often explaining a seemingly harsh action: 愛していればこそ.","examples":[{"ja":"子供を愛していればこそ、厳しく{叱|しか}るのだ。","en":"It's precisely because I love my child that I scold him strictly."},{"ja":"健康であればこそ、好きな仕事ができる。","en":"It's precisely because you're healthy that you can do the work you love."}],"id":"n1g82"},{"pattern":"〜ゆえ(に)","meaning":"because of ~; therefore","formation":"Plain form / Noun (の) + ゆえ(に) / (が)ゆえの + Noun","note":"Formal, literary equivalent of ため or から. Kanji form: 故.","examples":[{"ja":"彼は若さゆえに、失敗を恐れなかった。","en":"Because of his youth, he wasn't afraid of failure."},{"ja":"貧しいがゆえに、教育を受けられない子供もいる。","en":"Some children cannot get an education because they are poor."}],"id":"n1g83"},{"pattern":"〜こととて","meaning":"because ~ (as an excuse)","formation":"Plain form / Noun + の + こととて","note":"Formal, old-fashioned; used when apologizing or asking forgiveness: 慣れぬこととて.","examples":[{"ja":"子供のしたこととて、どうかお許しください。","en":"It was done by a child, so please forgive him."},{"ja":"慣れないこととて、ご迷惑をおかけしました。","en":"As I am not used to this, I'm afraid I have caused you trouble."}],"id":"n1g84"},{"pattern":"〜手前","meaning":"since ~ (out of concern for face); in front of ~","formation":"Verb (plain) / Noun + の + 手前","note":"Because of what one has said or done, or how others will see it, one must act accordingly.","examples":[{"ja":"絶対に勝つと言った手前、負けるわけにはいかない。","en":"Since I said I'd definitely win, I can't afford to lose."},{"ja":"子供の手前、夫婦げんかはしないようにしている。","en":"For the children's sake, we try not to argue in front of them."}],"id":"n1g85"},{"pattern":"〜だろうに","meaning":"would have ~ (but); surely ~ (and yet)","formation":"Plain form + だろうに","note":"Regret or sympathy about what would have been, or what surely is, contrary to reality.","examples":[{"ja":"もう少し早く出ていれば、間に合っただろうに。","en":"If we had left a little earlier, we would have made it in time."},{"ja":"疲れているだろうに、彼は笑顔で手伝ってくれた。","en":"He must have been tired, yet he helped me with a smile."}],"id":"n1g86"},{"pattern":"〜といい〜といい","meaning":"both ~ and ~; whether in ~ or ~","formation":"Noun A + といい + Noun B + といい","note":"Picks examples to evaluate the whole, with admiration or criticism.","examples":[{"ja":"この店は味といい値段といい、文句のつけようがない。","en":"In both taste and price, this restaurant is beyond criticism."},{"ja":"彼は顔といい声といい、父親にそっくりだ。","en":"In both his face and his voice, he's just like his father."}],"id":"n1g87"},{"pattern":"〜といわず〜といわず","meaning":"whether ~ or ~ (everywhere, all of it)","formation":"Noun A + といわず + Noun B + といわず","note":"Emphasizes 'all without distinction'; often with places, times or body parts.","examples":[{"ja":"子供は顔といわず手といわず、泥だらけだった。","en":"The child was covered in mud, face, hands and all."},{"ja":"彼は昼といわず夜といわず、研究に没頭している。","en":"He is absorbed in his research day and night."}],"id":"n1g88"},{"pattern":"〜なり〜なり","meaning":"either ~ or ~; ~ or something","formation":"Noun / Verb (dictionary form) + なり + Noun / Verb (dictionary form) + なり","note":"Gives examples as suggestions; usually followed by advice or requests. Not used for past events.","examples":[{"ja":"わからないことがあれば、先生に聞くなり辞書で調べるなりしなさい。","en":"If there's something you don't understand, ask the teacher or look it up in a dictionary."},{"ja":"電話なりメールなりで連絡してください。","en":"Please contact me by phone, email or some other way."}],"id":"n1g89"},{"pattern":"〜ずにはおかない/〜ないではおかない","meaning":"will definitely ~; cannot fail to (cause) ~","formation":"Verb (ない-stem) + ずにはおかない (する → せずにはおかない) / Verb (ない-form) + ではおかない","note":"Either a strong resolve, or something that inevitably causes a reaction (感動させずにはおかない).","examples":[{"ja":"この映画は見る人を感動させずにはおかない。","en":"This movie cannot fail to move those who see it."},{"ja":"今度こそ真相を明らかにせずにはおかない。","en":"This time, I will bring the truth to light no matter what."}],"id":"n1g90"},{"pattern":"〜ずにはすまない/〜ないではすまない","meaning":"must ~; will have to ~ (it can't be avoided)","formation":"Verb (ない-stem) + ずにはすまない (する → せずにはすまない) / Verb (ない-form) + ではすまない","note":"Given the situation or social norms, one cannot get away without doing something. Kanji form: 済まない.","examples":[{"ja":"人の物を壊したのだから、弁償せずにはすまない。","en":"Since you broke someone else's property, you'll have to pay for it."},{"ja":"こんな大きなミスをしたら、上司に報告しないではすまない。","en":"After a mistake this big, you can't get away without reporting it to your boss."}],"id":"n1g91"},{"pattern":"〜ではすまない/〜ではすまされない","meaning":"~ won't be enough; can't be settled with ~","formation":"Noun / Plain form + では(じゃ)すまない / ではすまされない","note":"The situation is too serious to end with a simple apology or excuse: 知らなかったではすまされない.","examples":[{"ja":"これほどの損害を出したら、謝るだけではすまない。","en":"After causing this much damage, an apology alone won't be enough."},{"ja":"社会人なら、「知らなかった」ではすまされない。","en":"As a working adult, 'I didn't know' is no excuse."}],"id":"n1g92"},{"pattern":"〜を余儀なくされる/〜を余儀なくさせる","meaning":"be forced to ~ / force (someone) to ~","formation":"Noun (action) + を余儀なくされる / を余儀なくさせる","note":"Formal; circumstances beyond one's control force an unwanted action. Common in news.","examples":[{"ja":"台風のため、大会は中止を余儀なくされた。","en":"Due to the typhoon, the tournament had to be canceled."},{"ja":"急激な円高が、多くの企業に方針転換を余儀なくさせた。","en":"The sharp rise of the yen forced many companies to change course."}],"id":"n1g93"},{"pattern":"〜までもない/〜までもなく","meaning":"there is no need to ~; it goes without ~","formation":"Verb (dictionary form) + までもない / までもなく","note":"Something is so obvious or minor that the action is unnecessary: 言うまでもなく.","examples":[{"ja":"言うまでもなく、健康は何よりも大切だ。","en":"Needless to say, health is more important than anything."},{"ja":"こんな簡単な修理は、専門家に頼むまでもない。","en":"There's no need to call a professional for such a simple repair."}],"id":"n1g94"},{"pattern":"〜までだ/〜までのことだ","meaning":"I'll just ~ (then); I merely ~","formation":"Verb (dictionary form) + までだ / Verb (た-form) + までだ","note":"Dictionary form: if all else fails, I'll simply do X. た-form: I only did X, nothing more.","examples":[{"ja":"バスがなければ、歩いて帰るまでだ。","en":"If there's no bus, I'll just walk home."},{"ja":"別に深い意味はない。思ったことを言ったまでのことだ。","en":"There's no deep meaning. I simply said what I thought."}],"id":"n1g95"},{"pattern":"〜にはあたらない","meaning":"there's no need to ~; it's not worth ~","formation":"Verb (dictionary form) / Noun + には(に)あたらない","note":"With 驚く, 非難する, 心配する, 感心する: the reaction isn't warranted. Kanji form: 当たらない.","examples":[{"ja":"彼の実力なら優勝は当然で、驚くにはあたらない。","en":"Given his ability, his victory is natural and nothing to be surprised about."},{"ja":"子供のいたずらだから、非難するにはあたらない。","en":"It's just a child's prank, so there's no need to criticize it."}],"id":"n1g96"},{"pattern":"〜には及ばない","meaning":"there is no need to ~","formation":"Verb (dictionary form) / Noun + には及ばない","note":"Polite way to say something is unnecessary, often to spare the listener trouble.","examples":[{"ja":"わざわざお越しいただくには及びません。","en":"There's no need for you to come all the way here."},{"ja":"軽い風邪ですから、ご心配には及びません。","en":"It's only a mild cold, so there's no need to worry."}],"id":"n1g97"},{"pattern":"〜てしかるべきだ","meaning":"should ~; it is only proper that ~","formation":"Verb (て-form) / い-Adj (〜くて) / な-Adj + で + しかるべきだ","note":"Formal; states what is appropriate or naturally expected. しかるべき + Noun means 'appropriate ~'.","examples":[{"ja":"彼の努力はもっと評価されてしかるべきだ。","en":"His efforts deserve more recognition."},{"ja":"事故の責任者は謝罪してしかるべきだ。","en":"The person responsible for the accident ought to apologize."}],"id":"n1g98"},{"pattern":"〜てもさしつかえない","meaning":"it's all right to ~; may ~","formation":"Verb (て-form) / い-Adj (〜くて) / な-Adj・Noun + で + もさしつかえない","note":"Formal permission, more polite than 〜てもいい. Kanji form: 差し支えない.","examples":[{"ja":"書類は鉛筆で書いてもさしつかえありません。","en":"You may fill out the documents in pencil."},{"ja":"体調が悪ければ、明日の会議は欠席してもさしつかえない。","en":"If you're not feeling well, it's fine to miss tomorrow's meeting."}],"id":"n1g99"},{"pattern":"〜べからず/〜べからざる","meaning":"must not ~; should not ~","formation":"Verb (dictionary form) + べからず / べからざる + Noun (する → すべからず)","note":"Literary prohibition on signs. べからざる modifies nouns: 欠くべからざる (indispensable).","examples":[{"ja":"芝生に入るべからず。","en":"Keep off the grass."},{"ja":"水は人間にとって欠くべからざるものだ。","en":"Water is indispensable to human beings."},{"ja":"彼の発言は許すべからざるものだ。","en":"His remarks are unforgivable."}],"id":"n1g100"},{"pattern":"〜まじき","meaning":"unbecoming of ~; should not ~","formation":"Verb (dictionary form) + まじき + Noun (する → すまじき); Noun + にあるまじき + Noun","note":"Most often as Noun + にあるまじき + Noun: behavior unacceptable for someone in that role.","examples":[{"ja":"生徒を殴るなど、教師にあるまじき行為だ。","en":"Hitting students is conduct unbecoming of a teacher."},{"ja":"{賄賂|わいろ}を受け取るとは、政治家として許すまじきことだ。","en":"Accepting bribes is unforgivable for a politician."}],"id":"n1g101"},{"pattern":"〜べくもない","meaning":"there's no way ~; cannot possibly ~","formation":"Verb (dictionary form) + べくもない (する → すべくもない)","note":"With 望む, 知る, 比べる: something is impossible, so hoping or comparing is pointless.","examples":[{"ja":"私の給料では、そんな高級車は望むべくもない。","en":"On my salary, owning such a luxury car is out of the question."},{"ja":"この絵は本物とは比べるべくもない。","en":"This painting can't even be compared with the real thing."}],"id":"n1g102"},{"pattern":"〜べく","meaning":"in order to ~; with the aim of ~","formation":"Verb (dictionary form) + べく (する → すべく / するべく)","note":"Formal, written purpose expression; the main clause is not a request or command.","examples":[{"ja":"彼は医者になるべく、毎日勉強に励んでいる。","en":"He studies hard every day in order to become a doctor."},{"ja":"事故の原因を究明すべく、調査が始まった。","en":"An investigation has begun to determine the cause of the accident."}],"id":"n1g103"},{"pattern":"〜んがため(に)","meaning":"in order to ~ (with strong determination)","formation":"Verb (ない-stem) + んがため(に) / んがための + Noun (する → せんがため)","note":"Literary; a strong, single-minded purpose. Set phrase: 生きんがため.","examples":[{"ja":"彼は夢を実現させんがため、必死に働いた。","en":"He worked desperately in order to make his dream come true."},{"ja":"生きんがために、盗みを働く者もいた。","en":"There were also those who resorted to stealing just to survive."}],"id":"n1g104"},{"pattern":"〜でなくてなんだろう","meaning":"if this isn't ~, what is?","formation":"Noun + でなくてなんだろう(か)","note":"Rhetorical, emotional emphasis; common in essays and literature.","examples":[{"ja":"命をかけて子供を守る。これが愛でなくてなんだろう。","en":"Risking one's life to protect a child: if this isn't love, what is?"},{"ja":"偶然同じ飛行機に乗り合わせるとは、運命でなくてなんだろうか。","en":"Happening to be on the same plane: if that isn't fate, what is?"}],"id":"n1g105"},{"pattern":"〜てはばからない","meaning":"not hesitate to ~; openly ~","formation":"Verb (て-form) + はばからない","note":"Says something boldly without regard for others; with 言う, 公言する, 断言する. Kanji form: 憚らない.","examples":[{"ja":"彼は自分が天才だと言ってはばからない。","en":"He doesn't hesitate to say that he's a genius."},{"ja":"社長は今年中に黒字化すると公言してはばからない。","en":"The president openly declares that the company will be in the black within this year."}],"id":"n1g106"},{"pattern":"〜をものともせず(に)","meaning":"undaunted by ~; in defiance of ~","formation":"Noun + をものともせず(に)","note":"Praises someone bravely overcoming obstacles; not used about oneself.","examples":[{"ja":"彼はけがをものともせず、最後まで戦った。","en":"Undaunted by his injury, he fought to the end."},{"ja":"登山隊は吹雪をものともせずに頂上を目指した。","en":"The climbing party pressed on toward the summit in defiance of the blizzard."}],"id":"n1g107"},{"pattern":"〜をよそに","meaning":"ignoring ~; regardless of (others' concern)","formation":"Noun + をよそに","note":"Acting with no regard for others' worries, expectations or criticism; often a negative nuance.","examples":[{"ja":"彼は親の心配をよそに、毎晩遊び歩いている。","en":"Ignoring his parents' worries, he goes out partying every night."},{"ja":"住民の反対をよそに、工事が始まった。","en":"Construction began despite the residents' opposition."}],"id":"n1g108"},{"pattern":"〜をいいことに","meaning":"taking advantage of ~","formation":"Noun / Plain form + の + をいいことに","note":"Exploits a situation for selfish ends; critical nuance.","examples":[{"ja":"先生がいないのをいいことに、生徒たちは騒ぎ始めた。","en":"Taking advantage of the teacher's absence, the students started making a racket."},{"ja":"彼は上司が優しいのをいいことに、遅刻ばかりしている。","en":"Taking advantage of his boss's kindness, he's constantly late."}],"id":"n1g109"},{"pattern":"〜をおして","meaning":"despite ~; pushing through ~","formation":"Noun + をおして","note":"Doing something in spite of a hardship such as illness or opposition: 病をおして. Kanji form: 押して.","examples":[{"ja":"彼は病をおして会議に出席した。","en":"He attended the meeting despite being ill."},{"ja":"周囲の反対をおして、彼女は留学を決めた。","en":"She decided to study abroad despite the opposition of those around her."}],"id":"n1g110"},{"pattern":"〜をいとわず","meaning":"not minding ~; willing to (endure) ~","formation":"Noun / Verb (dictionary form) + の + をいとわず","note":"Willingly accepts hardship for a goal: 労をいとわず, 危険をいとわず. Kanji form: 厭わず.","examples":[{"ja":"彼は労をいとわず、困っている人を助ける。","en":"He spares no effort to help people in need."},{"ja":"彼女は遠くまで通うのをいとわず、その学校を選んだ。","en":"Not minding the long commute, she chose that school."}],"id":"n1g111"},{"pattern":"〜にかこつけて","meaning":"using ~ as an excuse","formation":"Noun + にかこつけて","note":"Uses an unrelated matter as a pretext to do what one wants. Kanji form: 託けて.","examples":[{"ja":"彼は仕事にかこつけて、よく海外旅行をしている。","en":"He often travels abroad, using work as an excuse."},{"ja":"父の病気にかこつけて、会社を休んだ。","en":"I took a day off work, using my father's illness as an excuse."}],"id":"n1g112"},{"pattern":"〜にかまけて","meaning":"being too wrapped up in ~ (to do something else)","formation":"Noun + にかまけて","note":"Absorption in one thing leads to neglecting something important; often self-critical.","examples":[{"ja":"仕事にかまけて、家族との時間をおろそかにしていた。","en":"Being too wrapped up in work, I neglected time with my family."},{"ja":"遊びにかまけて、勉強をまったくしなかった。","en":"I was so caught up in having fun that I didn't study at all."}],"id":"n1g113"},{"pattern":"〜にひきかえ","meaning":"in contrast to ~; compared with ~","formation":"Noun / Plain form + の + にひきかえ","note":"Contrasts two things, often with a subjective, evaluative tone. Kanji form: 引き換え.","examples":[{"ja":"社交的な兄にひきかえ、弟はおとなしい。","en":"In contrast to his outgoing older brother, the younger brother is quiet."},{"ja":"去年にひきかえ、今年は売り上げが好調だ。","en":"In contrast to last year, sales are strong this year."}],"id":"n1g114"},{"pattern":"〜にもまして","meaning":"even more than ~; above ~","formation":"Noun + にもまして","note":"Exceeds a previous level. 何にもまして: above all. いつにもまして: more than ever.","examples":[{"ja":"今年の夏は去年にもまして暑い。","en":"This summer is even hotter than last year."},{"ja":"何にもまして大切なのは、家族の健康だ。","en":"What matters above all is my family's health."}],"id":"n1g115"},{"pattern":"〜と相まって","meaning":"combined with ~; coupled with ~","formation":"Noun + と相まって / Noun A と Noun B が相まって","note":"Two factors work together to produce a greater effect.","examples":[{"ja":"美しい音楽が映像と相まって、観客を感動させた。","en":"The beautiful music, combined with the visuals, moved the audience."},{"ja":"努力と才能が相まって、彼は大成功を収めた。","en":"His effort and talent together brought him great success."}],"id":"n1g116"},{"pattern":"〜とは","meaning":"to think that ~; I can't believe ~","formation":"Plain form + とは","note":"Expresses surprise, admiration or disgust; the rest of the sentence is often left unsaid.","examples":[{"ja":"あの真面目な彼がうそをつくとは。","en":"To think that such a serious guy would lie!"},{"ja":"一人でこんなに大きな家を建てたとは、驚きだ。","en":"It's amazing that he built such a big house by himself."}],"id":"n1g117"},{"pattern":"〜ときたら","meaning":"when it comes to ~; as for ~ (complaint)","formation":"Noun + ときたら","note":"Introduces a familiar topic followed by criticism or dissatisfaction; conversational.","examples":[{"ja":"うちの息子ときたら、毎日ゲームばかりしている。","en":"As for my son, all he does is play video games every day."},{"ja":"この店ときたら、値段は高いし店員の態度も悪い。","en":"Honestly, this store: prices are high and the staff are rude."}],"id":"n1g118"},{"pattern":"〜ともなく/〜ともなしに","meaning":"without really meaning to ~; absentmindedly","formation":"Verb (dictionary form) + ともなく / ともなしに; Question word (+ particle) + ともなく","note":"Unintentional action (見るともなく見る). With question words: unspecified (どこからともなく = from somewhere).","examples":[{"ja":"テレビを見るともなく見ていたら、友達が映っていた。","en":"I was idly watching TV when my friend appeared on screen."},{"ja":"どこからともなく、いい香りが漂ってきた。","en":"A pleasant fragrance drifted in from somewhere."}],"id":"n1g119"},{"pattern":"〜とばかりに","meaning":"as if to say ~","formation":"Plain form / Imperative / Quote + とばかりに","note":"An action that clearly shows what someone feels, as though they said it. Describes others, not oneself.","examples":[{"ja":"彼女は「もう帰れ」とばかりに私をにらんだ。","en":"She glared at me as if to say, 'Go home already.'"},{"ja":"ここがチャンスとばかりに、彼は一気に攻めた。","en":"Seizing what he saw as his chance, he launched an all-out attack."}],"id":"n1g120"},{"pattern":"〜んばかりに","meaning":"as if about to ~; almost ~","formation":"Verb (ない-stem) + んばかりに / んばかりの + Noun (する → せんばかり)","note":"A state so extreme it seems about to happen: 泣かんばかり, 言わんばかり, あふれんばかり.","examples":[{"ja":"彼女は泣かんばかりの顔で頼んできた。","en":"She begged me, looking as if she was about to cry."},{"ja":"彼は「お前のせいだ」と言わんばかりに私を見た。","en":"He looked at me as if to say, 'It's your fault.'"},{"ja":"会場はあふれんばかりの観客で埋め尽くされた。","en":"The venue was packed with a crowd so large it seemed about to overflow."}],"id":"n1g121"},{"pattern":"〜ごとく/〜ごとき","meaning":"like ~; as ~","formation":"Verb (plain) + (が)ごとく / Noun + の + ごとく / ごとき + Noun; Noun + ごとき","note":"Literary ように/ような. Noun + ごとき can also show contempt or humility: 私ごとき (someone like me).","examples":[{"ja":"時間は矢のごとく過ぎていく。","en":"Time flies like an arrow."},{"ja":"彼は何も知らないかのごとく振る舞った。","en":"He behaved as if he knew nothing."},{"ja":"私ごときに、こんな大役が務まるでしょうか。","en":"Could someone like me really handle such an important role?"}],"id":"n1g122"},{"pattern":"〜めく","meaning":"to show signs of ~; to become ~-like","formation":"Noun + めく / めいた + Noun","note":"Limited set of words: 春めく, 秋めく, 謎めく, 冗談めく, 皮肉めいた, 言い訳めいた.","examples":[{"ja":"三月に入り、日差しも春めいてきた。","en":"Now that it's March, the sunlight has begun to feel like spring."},{"ja":"彼は冗談めいた口調で本音を言った。","en":"He said what he really thought in a joking tone."}],"id":"n1g123"},{"pattern":"〜じみる","meaning":"to look like ~; to smack of ~","formation":"Noun + じみる / じみた + Noun","note":"Usually negative: 子供じみた, 年寄りじみた, 説教じみた. Also physical: 汗じみた (sweat-stained).","examples":[{"ja":"そんな子供じみたことはやめなさい。","en":"Stop doing such childish things."},{"ja":"彼の話はどこか説教じみていて、聞く気になれない。","en":"His talk is somehow preachy, so I don't feel like listening."}],"id":"n1g124"},{"pattern":"〜ぶる","meaning":"to act ~; to pretend to be ~","formation":"Noun / い-Adj (stem) / な-Adj (stem) + ぶる / ぶった + Noun","note":"Negative nuance of putting on airs: 偉ぶる, 上品ぶる, 大人ぶる, 善人ぶる.","examples":[{"ja":"彼は上品ぶっているが、本当はがさつだ。","en":"He acts refined, but he's actually crude."},{"ja":"先輩だからといって偉ぶるのはよくない。","en":"It's not good to act superior just because you're a senior."}],"id":"n1g125"},{"pattern":"〜がましい","meaning":"-ish; smacking of ~ (unpleasantly)","formation":"Noun / Verb (ます-stem) + がましい","note":"Limited set with a negative tone: 恩着せがましい, 押し付けがましい, 言い訳がましい, 未練がましい.","examples":[{"ja":"彼の言い方は恩着せがましい。","en":"The way he says it makes it sound like he's doing you a huge favor."},{"ja":"言い訳がましいことは言いたくないが、電車が遅れたんです。","en":"I don't want to sound like I'm making excuses, but the train was late."}],"id":"n1g126"},{"pattern":"〜まみれ","meaning":"covered in ~; smeared with ~","formation":"Noun + まみれ","note":"Covered all over with something unpleasant: 泥まみれ, 汗まみれ, 血まみれ, ほこりまみれ.","examples":[{"ja":"子供たちは泥まみれになって遊んでいた。","en":"The children were playing, covered in mud."},{"ja":"倉庫の中の箱はほこりまみれだった。","en":"The boxes in the warehouse were covered in dust."}],"id":"n1g127"},{"pattern":"〜ずくめ","meaning":"entirely ~; nothing but ~","formation":"Noun + ずくめ","note":"Something is full of one thing: 黒ずくめ, いいことずくめ, ごちそうずくめ, 規則ずくめ.","examples":[{"ja":"今年は結婚に昇進にと、いいことずくめの一年だった。","en":"With my wedding and promotion, this year was full of nothing but good things."},{"ja":"黒ずくめの男が店に入ってきた。","en":"A man dressed all in black came into the shop."}],"id":"n1g128"},{"pattern":"〜ながらに/〜ながらの","meaning":"while (remaining) ~; as (it has always been)","formation":"Noun / Verb (ます-stem) + ながらに / ながらの + Noun","note":"Set phrases: 涙ながらに, 生まれながらに, 昔ながらの, いながらにして.","examples":[{"ja":"彼女は涙ながらに事故のことを語った。","en":"She spoke about the accident in tears."},{"ja":"この店では昔ながらの製法で豆腐を作っている。","en":"This shop makes tofu using traditional methods."},{"ja":"インターネットのおかげで、家にいながらにして買い物ができる。","en":"Thanks to the internet, you can shop without leaving home."}],"id":"n1g129"},{"pattern":"〜きらいがある","meaning":"tend to ~ (undesirable tendency)","formation":"Verb (dictionary form / ない-form) / Noun + の + きらいがある","note":"Points out a bad habit or tendency, often in written criticism. Kanji form: 嫌いがある.","examples":[{"ja":"彼は物事を悲観的に考えるきらいがある。","en":"He has a tendency to see things pessimistically."},{"ja":"最近の若者は、何でもネットで済ませるきらいがある。","en":"Young people these days tend to do everything online."}],"id":"n1g130"},{"pattern":"〜しまつだ","meaning":"end up ~ (a bad result)","formation":"Verb (dictionary form) + しまつだ / この・あの + しまつだ","note":"After a series of bad events, things end in an even worse result; critical tone. Kanji form: 始末だ.","examples":[{"ja":"息子は勉強をせず、ついには学校をやめると言い出すしまつだ。","en":"My son doesn't study, and now he's even started saying he'll quit school."},{"ja":"彼は遅刻ばかりで、最後には会議そのものを忘れるしまつだった。","en":"He was always late, and in the end he even forgot the meeting altogether."}],"id":"n1g131"},{"pattern":"〜ずじまい","meaning":"end up never ~; never got to ~","formation":"Verb (ない-stem) + ずじまい (する → せずじまい)","note":"Something intended was ultimately never done, with regret. Used for past events.","examples":[{"ja":"旅行の間雨が続いて、富士山は見えずじまいだった。","en":"It kept raining during the trip, and we never got to see Mt. Fuji."},{"ja":"忙しくて、彼にお礼を言わずじまいになってしまった。","en":"I was so busy that I never got around to thanking him."}],"id":"n1g132"},{"pattern":"〜つ〜つ","meaning":"alternately ~ and ~; back and forth","formation":"Verb A (ます-stem) + つ + Verb B (ます-stem) + つ","note":"Set phrases with paired or opposite verbs: 持ちつ持たれつ, 行きつ戻りつ, 抜きつ抜かれつ.","examples":[{"ja":"彼は駅の前を行きつ戻りつしていた。","en":"He was pacing back and forth in front of the station."},{"ja":"世の中は持ちつ持たれつだ。","en":"Life is all about give and take."}],"id":"n1g133"},{"pattern":"〜かれ〜かれ","meaning":"whether ~ or ~","formation":"い-Adj (stem) + かれ + opposite い-Adj (stem) + かれ","note":"Fixed phrases only: 遅かれ早かれ (sooner or later), 多かれ少なかれ (more or less), 善かれ悪しかれ.","examples":[{"ja":"遅かれ早かれ、真実は明らかになるだろう。","en":"Sooner or later, the truth will come out."},{"ja":"多かれ少なかれ、{誰|だれ}にでも悩みはある。","en":"Everyone has worries, to a greater or lesser extent."}],"id":"n1g134"},{"pattern":"〜なりとも","meaning":"at least ~; even (a little)","formation":"Noun (small quantity) + なりとも","note":"A modest wish or offer of a minimal amount: 少しなりとも, 多少なりとも, 一目なりとも.","examples":[{"ja":"少しなりとも、お役に立てれば幸いです。","en":"I'd be happy if I could be of even a little help."},{"ja":"一目なりとも、故郷の母に会いたい。","en":"I want to see my mother back home, even if only for a moment."}],"id":"n1g135"},{"pattern":"〜といったところだ","meaning":"about ~; roughly ~ (not much)","formation":"Noun / Verb (dictionary form) + といったところだ","note":"Gives a modest estimate or level, implying it isn't much; often with せいぜい.","examples":[{"ja":"参加者はせいぜい三十人といったところだ。","en":"There will be about thirty participants at most."},{"ja":"私の料理の腕前は、まあまあといったところだ。","en":"My cooking skills are, well, so-so."}],"id":"n1g136"},{"pattern":"〜とみえる","meaning":"it seems that ~; apparently ~","formation":"Plain form + とみえる / とみえて","note":"A conclusion drawn from what the speaker observes. Kanji form: と見える.","examples":[{"ja":"彼は疲れているとみえて、電車の中でずっと寝ていた。","en":"He seemed tired; he slept the whole time on the train."},{"ja":"道が{濡|ぬ}れている。夜中に雨が降ったとみえる。","en":"The road is wet. It seems it rained during the night."}],"id":"n1g137"},{"pattern":"〜をして〜させる","meaning":"to make (someone) ~","formation":"Noun (person) + をして + Verb (causative / 〜しめる)","note":"Literary causative; stresses that even a notable person was made to feel or do something.","examples":[{"ja":"彼の演奏は、厳しい批評家をして絶賛させた。","en":"His performance made even the harshest critics rave."},{"ja":"何が彼をしてそこまで言わしめたのだろうか。","en":"What could have driven him to say so much?"}],"id":"n1g138"},{"pattern":"〜べくして","meaning":"as was bound to happen; inevitably","formation":"Verb (dictionary form) + べくして + same Verb (た-form)","note":"Something happened just as it naturally should have: 起こるべくして起こった.","examples":[{"ja":"あれは起こるべくして起こった事故だ。","en":"That accident was bound to happen."},{"ja":"彼は練習を重ね、勝つべくして勝った。","en":"He trained relentlessly and won, just as he was meant to."}],"id":"n1g139"},{"pattern":"〜でもなんでもない","meaning":"not ~ at all","formation":"Noun / な-Adj + でもなんでもない; い-Adj (〜く) + もなんともない","note":"Strongly denies a claim or assumption. い-adjectives take 〜くもなんともない.","examples":[{"ja":"彼とは友達でもなんでもない。ただの知り合いだ。","en":"He's not my friend or anything. He's just an acquaintance."},{"ja":"こんな映画、怖くもなんともない。","en":"This movie isn't scary in the least."}],"id":"n1g140"},{"pattern":"〜とうってかわって","meaning":"in complete contrast to ~; totally changed from ~","formation":"Noun + とうってかわって","note":"A sudden, drastic change from a previous state. Kanji form: 打って変わって.","examples":[{"ja":"昨日とうってかわって、今日はいい天気だ。","en":"In complete contrast to yesterday, the weather is beautiful today."},{"ja":"彼は以前とうってかわって、真面目に働くようになった。","en":"He's completely changed from before and now works diligently."}],"id":"n1g141"},{"pattern":"〜てまで/〜までして","meaning":"even going so far as to ~","formation":"Verb (て-form) + まで / Noun + までして","note":"Stresses or questions an extreme means used to achieve something: 借金してまで, 徹夜までして.","examples":[{"ja":"借金をしてまで、高い車を買う必要はない。","en":"There's no need to go so far as to borrow money to buy an expensive car."},{"ja":"彼は徹夜までして報告書を仕上げた。","en":"He even stayed up all night to finish the report."}],"id":"n1g142"},{"pattern":"〜かいがある/〜かいもなく","meaning":"worth ~; pays off / in vain despite ~","formation":"Verb (dictionary form / た-form) / Noun + の + かいがある / かいもなく","note":"かいがある: the effort paid off. かいもなく: the effort was in vain. Kanji form: 甲斐.","examples":[{"ja":"一生懸命練習したかいがあって、試合に勝てた。","en":"All our hard practice paid off, and we won the match."},{"ja":"家族の看病のかいもなく、祖父は亡くなった。","en":"Despite the family's devoted care, my grandfather passed away."}],"id":"n1g143"},{"pattern":"〜ためしがない","meaning":"have never (once) ~","formation":"Verb (た-form) + ためしがない","note":"Critical tone: something has never happened even once, so don't expect it now. Kanji form: 試しがない.","examples":[{"ja":"彼は約束の時間を守ったためしがない。","en":"He has never once been on time for an appointment."},{"ja":"兄にお金を貸して、返ってきたためしがない。","en":"Whenever I lend my brother money, I've never once gotten it back."}],"id":"n1g144"},{"pattern":"〜と言っても過言ではない","meaning":"it is no exaggeration to say ~","formation":"Plain form + と言っても過言ではない","note":"Formal; makes a strong claim while insisting it isn't overstated.","examples":[{"ja":"彼は日本一の料理人と言っても過言ではない。","en":"It's no exaggeration to say he's the best chef in Japan."},{"ja":"この発明は世界を変えたと言っても過言ではない。","en":"It's no exaggeration to say this invention changed the world."}],"id":"n1g145"},{"pattern":"〜に先駆けて","meaning":"ahead of ~; before others","formation":"Noun + に先駆けて","note":"Being the first to do something; common with 世界, 他社, 全国.","examples":[{"ja":"その会社は他社に先駆けて新製品を発売した。","en":"The company released the new product ahead of its competitors."},{"ja":"この町は全国に先駆けて、ごみの有料化を始めた。","en":"This town began charging for garbage collection ahead of the rest of the country."}],"id":"n1g146"},{"pattern":"〜すべがない","meaning":"there is no way to ~","formation":"Verb (dictionary form) + すべがない / すべもない","note":"Literary; no means is available. Kanji form: 術がない. なすすべもない = completely helpless.","examples":[{"ja":"彼の連絡先がわからないので、知らせるすべがない。","en":"I don't know his contact details, so there's no way to let him know."},{"ja":"圧倒的な力の差に、私たちはなすすべもなかった。","en":"Against such an overwhelming difference in strength, we were helpless."}],"id":"n1g147"},{"pattern":"〜てはかなわない","meaning":"can't stand ~; it's unbearable if ~","formation":"Verb (て-form) / い-Adj (〜くて) + は + かなわない (casual: 〜ちゃかなわない)","note":"The situation is too troublesome to put up with. Kanji form: 敵わない.","examples":[{"ja":"こう毎日暑くてはかなわない。","en":"I can't stand it being this hot every day."},{"ja":"夜中に何度も電話をかけてこられてはかなわない。","en":"I can't put up with being called again and again in the middle of the night."}],"id":"n1g148"},{"pattern":"〜のではあるまいか","meaning":"isn't it (the case) that ~?; I suspect that ~","formation":"Plain form (な-Adj / Noun + な) + のではあるまいか","note":"Formal, written version of 〜のではないだろうか; states the writer's cautious opinion.","examples":[{"ja":"この計画は実現が難しいのではあるまいか。","en":"Isn't this plan going to be difficult to carry out?"},{"ja":"彼は何か隠しているのではあるまいか。","en":"I suspect he may be hiding something."}],"id":"n1g149"}];